import { expect, test } from './browser-test.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { loadFixedBoard } from './game-fixture.ts';
import { boardGaps } from './focus-bounds.ts';
import type { Locator, Page } from '@playwright/test';

const SIZE = 16;
const LAST = SIZE ** 2 - 1;
// Pressed 4px inside the board edge, so the card shows only a sliver there.
const EDGE_INSET_PX = 4;
const WHEEL_PX = 240;
const SUBPIXEL_PX = 0.25;
// The two stated viewports, and the zoomed one at 640x400 where a card can be clipped.
const VIEWS = [
  { width: 360, height: 800, scale: 1 },
  { width: 1280, height: 800, scale: 1 },
  { width: 640, height: 400, scale: 2 },
] as const;
const TOUCH_VIEWS = VIEWS;
// A busy machine can show one unchanged frame while a scroll still runs, so the wheel waits for several.
const SETTLED_FRAMES = 10;

// After the press completes, the focused card sits fully inside the board and the window, with
// nearest alignment leaving just the card's scroll margin at the edge it came in by.
async function expectSettledInView(card: Locator, message: string): Promise<void> {
  await expect(card).toBeFocused();
  const gaps = await boardGaps(card);
  // Scroll offsets are whole pixels, so fractional card sizes can leave up to 1px more.
  expect(gaps.bottom, message).toBeGreaterThanOrEqual(gaps.margin - SUBPIXEL_PX);
  expect(gaps.bottom, message).toBeLessThan(gaps.margin + 1);
  const box = await card.boundingBox();
  const view = card.page().viewportSize();
  if (!box || !view) throw new Error('Missing card or viewport.');
  expect(box.y + box.height, message).toBeLessThanOrEqual(view.height);
}

async function largeBoard(page: Page): Promise<Locator> {
  await loadFixedBoard(page);
  await page.getByLabel(DealControl.size, { exact: true }).selectOption(String(SIZE));
  const cards = page.locator('.card');
  await expect(cards).toHaveCount(SIZE ** 2);
  return cards;
}

async function restart(page: Page): Promise<void> {
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('.card.revealed')).toHaveCount(0);
}

// A programmatic scroll that brings the board's bottom edge into the window.
function showBoardEnd(page: Page): Promise<void> {
  return page
    .locator('.board-viewport')
    .evaluate((viewport) => viewport.scrollIntoView({ block: 'end' }));
}

// The first visible card that the board's bottom edge cuts through, with room to press its sliver.
// When a row boundary sits on the edge, a programmatic board scroll of half a card moves one there.
function clippedPoint(page: Page) {
  return page.locator('.board-viewport').evaluate((viewport, inset) => {
    const outer = viewport.getBoundingClientRect();
    const bottom = outer.top + viewport.clientTop + viewport.clientHeight;
    const cards = [...viewport.querySelectorAll('.card')];
    const crossing = () =>
      cards.findIndex((card) => {
        const box = card.getBoundingClientRect();
        return box.top < bottom - 2 * inset && box.bottom > bottom && box.left >= outer.left;
      });
    let index = crossing();
    if (index < 0) {
      viewport.scrollTop += (cards[0]?.getBoundingClientRect().height ?? 0) / 2;
      index = crossing();
    }
    const box = cards[index]?.getBoundingClientRect();
    if (!box) throw new Error('No card crosses the board edge.');
    return { index, x: box.left + box.width / 2, y: bottom - inset };
  }, EDGE_INSET_PX);
}

// Waits until the wheel's scroll has landed, so the pressed card is the one under the pointer.
async function wheelBoard(page: Page): Promise<void> {
  const viewport = page.locator('.board-viewport');
  const before = await viewport.evaluate((element) => element.scrollTop);
  await page.mouse.wheel(0, WHEEL_PX);
  await expect.poll(() => viewport.evaluate((element) => element.scrollTop)).not.toBe(before);
  await viewport.evaluate(
    (element, frames) =>
      new Promise<void>((settled) => {
        let last = element.scrollTop;
        let stable = 0;
        const check = () => {
          stable = element.scrollTop === last ? stable + 1 : 0;
          last = element.scrollTop;
          if (stable >= frames) settled();
          else requestAnimationFrame(check);
        };
        requestAnimationFrame(check);
      }),
    SETTLED_FRAMES,
  );
}

for (const view of VIEWS)
  test(
    `pointer clicks reveal the pressed card on ${SIZE}x${SIZE} at ${view.width}x${view.height}`,
    async ({ page }) => {
      const cards = await largeBoard(page);
      await cards.nth(LAST).click();
      await expect(cards.nth(LAST), 'I01 click after scrolling into view').toHaveClass(/revealed/);
      await restart(page);
      await page.locator('summary').click();
      await page.getByRole('button', { name: ReproductionControl.exportSnapshot }).click();
      await page.locator('summary').click();
      await cards.nth(1).click();
      await expect(cards.nth(1), 'I01 click after a jump from the panel').toHaveClass(/revealed/);
      await restart(page);
      await showBoardEnd(page);
      const board = await page.locator('.board-viewport').boundingBox();
      if (!board) throw new Error('Missing board.');
      await page.mouse.move(board.x + board.width / 2, board.y + board.height / 2);
      await wheelBoard(page);
      const wheeled = await clippedPoint(page);
      await page.mouse.click(wheeled.x, wheeled.y);
      await expect(cards.nth(wheeled.index), 'I01 click after a wheel scroll').toHaveClass(
        /revealed/,
      );
      await restart(page);
      await showBoardEnd(page);
      const clipped = await clippedPoint(page);
      await page.mouse.click(clipped.x, clipped.y);
      await expect(cards.nth(clipped.index), 'V19 click on a clipped card').toHaveClass(/revealed/);
      await expectSettledInView(cards.nth(clipped.index), 'I13 a clicked card ends in view');
    },
    { viewport: { width: view.width, height: view.height }, deviceScaleFactor: view.scale },
  );

for (const view of TOUCH_VIEWS)
  test(
    `taps reveal the tapped card after a scroll and at a clipped edge at ${view.width}x${view.height}`,
    async ({ page }) => {
      const cards = await largeBoard(page);
      await page.evaluate(() => scrollTo(0, document.documentElement.scrollHeight));
      const point = await cards.nth(1).evaluate((card) => {
        card.closest('.board-viewport')?.scrollIntoView({ block: 'start' });
        const box = card.getBoundingClientRect();
        return { x: box.left + box.width / 2, y: box.top + box.height / 2 };
      });
      await page.touchscreen.tap(point.x, point.y);
      await expect(cards.nth(1), 'I01 tap after a programmatic scroll').toHaveClass(/revealed/);
      await restart(page);
      await showBoardEnd(page);
      const clipped = await clippedPoint(page);
      await page.touchscreen.tap(clipped.x, clipped.y);
      await expect(cards.nth(clipped.index), 'V19 tap on a clipped card').toHaveClass(/revealed/);
      await expectSettledInView(cards.nth(clipped.index), 'I13 a tapped card ends in view');
    },
    {
      viewport: { width: view.width, height: view.height },
      deviceScaleFactor: view.scale,
      hasTouch: true,
      isMobile: true,
    },
  );
import assert from 'node:assert/strict';
import { before, after, test as nodeTest } from 'node:test';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { chromium, expect as playwrightExpect } from '@playwright/test';
import { spawnSync } from 'node:child_process';
import { REFERENCE_ROOT, serveArtifact } from './artifact-server.ts';
import type { Browser, BrowserContext, BrowserContextOptions, Page } from '@playwright/test';

const BROWSER_TEMP = join(REFERENCE_ROOT, '.browser-work');
const RESULTS = join(REFERENCE_ROOT, 'test-results');
const CHROMIUM_VERSION = '156.0.8078.4';
const EXECUTABLE_ENV = 'PLAYWRIGHT_CHROMIUM_EXECUTABLE';
// Set to 1 for named-combination evidence. Other supported runtimes run and record their versions.
const NAMED_COMBINATION_ENV = 'NEON_PAIRS_NAMED_COMBINATION';
const NAMED_COMBINATION = {
  node: '26.12.1',
  npm: '11.20.0',
  playwright: '1.64.1',
  chromium: CHROMIUM_VERSION,
};
// Playwright hides scrollbars by default. Visible ones take layout space, as on a Windows desktop.
const HIDE_SCROLLBARS = '--hide-scrollbars';
export const Scrollbars = { hidden: 'hidden', visible: 'visible' } as const;
type ScrollbarMode = (typeof Scrollbars)[keyof typeof Scrollbars];
// A busy verifier runs many browsers at once, so a single wait gets more than Playwright's 5s default.
export const expect = playwrightExpect.configure({ timeout: 15_000 });
// Most journeys fit the standard limit. The accessibility journey and the large boards take the long one.
export const TestTimeouts = { standard: 30_000, long: 90_000 } as const;
// npm names itself and its version to every script it runs, so a browser file needs no npm process of its own.
const NPM_AGENT_ENV = 'npm_config_user_agent';
let browser: Browser | undefined;
let scrollbarBrowser: Promise<Browser> | undefined;
let artifact: Awaited<ReturnType<typeof serveArtifact>> | undefined;

before(async () => {
  await mkdir(BROWSER_TEMP, { recursive: true });
  await mkdir(RESULTS, { recursive: true });
  process.env.TEMP = BROWSER_TEMP;
  process.env.TMP = BROWSER_TEMP;
  const npm = /^npm\/(\S+)/.exec(process.env[NPM_AGENT_ENV] ?? '')?.[1] ?? npmVersion();
  const playwright: unknown = JSON.parse(
    await readFile(new URL(import.meta.resolve('@playwright/test/package.json')), 'utf8'),
  );
  assert.ok(playwright && typeof playwright === 'object' && 'version' in playwright);
  browser = await launch(Scrollbars.hidden);
  const runtime = {
    node: process.versions.node,
    npm,
    playwright: String(playwright.version),
    chromium: browser.version(),
  };
  const named = process.env[NAMED_COMBINATION_ENV] === '1';
  await writeFile(
    join(RESULTS, 'browser-runtime.json'),
    JSON.stringify({ ...runtime, namedCombination: named }, null, 2),
  );
  if (named) assert.deepEqual(runtime, NAMED_COMBINATION, 'T03 named combination');
  artifact = await serveArtifact();
});

after(async () => {
  await browser?.close();
  await (await scrollbarBrowser)?.close();
  await artifact?.close();
});

function launch(scrollbars: ScrollbarMode): Promise<Browser> {
  const executable = process.env[EXECUTABLE_ENV];
  return chromium.launch({
    headless: true,
    ...(executable ? { executablePath: executable } : {}),
    ...(scrollbars === Scrollbars.visible ? { ignoreDefaultArgs: [HIDE_SCROLLBARS] } : {}),
  });
}

interface BrowserFixture {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  gameURL: string;
}
interface Artifacts {
  outputPath(file: string): string;
}

function npmVersion(): string {
  const npmResult =
    process.platform === 'win32'
      ? spawnSync('cmd.exe', ['/d', '/c', 'npm --version'], { encoding: 'utf8' })
      : spawnSync('npm', ['--version'], { encoding: 'utf8' });
  assert.equal(npmResult.status, 0, 'T03 npm version command');
  return npmResult.stdout.trim();
}

export function test(
  name: string,
  body: (fixture: BrowserFixture, artifacts: Artifacts) => Promise<void>,
  options: BrowserContextOptions = {},
  scrollbars: ScrollbarMode = Scrollbars.hidden,
  timeout: number = TestTimeouts.standard,
): void {
  nodeTest(name, { timeout }, async (t) => {
    if (!browser || !artifact) throw new Error('Browser verification did not start.');
    const owner =
      scrollbars === Scrollbars.visible ? await (scrollbarBrowser ??= launch(scrollbars)) : browser;
    const context = await owner.newContext(options);
    t.after(() => context.close());
    const page = await context.newPage();
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));
    const directory = join(RESULTS, name.replace(/[^a-z0-9]+/gi, '-'));
    await mkdir(directory, { recursive: true });
    const artifacts = {
      outputPath(file: string): string {
        if (basename(file) !== file) throw new Error('Expected an artifact filename.');
        return join(directory, file);
      },
    };
    await body({ browser: owner, context, page, gameURL: artifact.url }, artifacts);
    assert.deepEqual(pageErrors, []);
  });
}

import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import { faceUpCards } from '../game.ts';
import { Card } from './Card.tsx';
import { useBoardFocus } from './use-board-focus.ts';
import type { CSSProperties, RefObject } from 'react';
import type { GameState } from '../game.ts';
import './board.css';

interface BoardProps {
  game: GameState;
  ref: RefObject<BoardFocus | null>;
  activate(index: number): void;
}
const NEAREST: ScrollIntoViewOptions = { block: 'nearest', inline: 'nearest' };
interface BoardStyle extends CSSProperties {
  '--grid-size': number;
}

export interface BoardFocus {
  focusRemembered(): void;
}

// Once a click or tap completes, the focused card can move fully into view.
function cardClicked(card: HTMLElement): void {
  card.scrollIntoView(NEAREST);
}

export function Board({ game, ref, activate }: BoardProps) {
  const { size, deck, matched, selection } = game;
  const { viewport, element, focused, focusRemembered, cardFocused } =
    useBoardFocus();
  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
  const matchedCards = useMemo(() => new Set(matched), [matched]);
  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
  const latestActivate = useRef(activate);
  useLayoutEffect(() => {
    latestActivate.current = activate;
  });
  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
  const style: BoardStyle = { '--grid-size': size };
  return (
    <div
      ref={viewport}
      className="board-viewport"
      role="region"
      aria-label="Game board"
      aria-describedby="board-help"
    >
      <div className="board" ref={element} style={style}>
        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            clicked={cardClicked}
          />
        ))}
      </div>
    </div>
  );
}
import { useCallback, useRef, useState } from 'react';
import { useNearestScroll } from './nearest-scroll.ts';

const KEYBOARD_FOCUS = ':focus-visible';

// Keeps the board's remembered tab stop and scrolls keyboard focus into view with nearest
// alignment.
export function useBoardFocus() {
  const viewport = useRef<HTMLDivElement>(null);
  const element = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(0);
  const scrollToNearest = useNearestScroll(viewport);
  // Focus calls skip the browser's centering scroll and then scroll with nearest alignment.
  const focusRemembered = useCallback(() => {
    const card = element.current?.querySelectorAll('button').item(focused);
    card?.focus({ preventScroll: true });
    if (card) scrollToNearest(card);
  }, [focused, scrollToNearest]);
  const cardFocused = useCallback(
    (index: number, card: HTMLElement): void => {
      setFocused(index);
      // Moving a card under a pressed pointer would send the release elsewhere and lose the click.
      if (card.matches(KEYBOARD_FOCUS)) scrollToNearest(card);
    },
    [scrollToNearest],
  );
  return { viewport, element, focused, focusRemembered, cardFocused };
}
import { memo } from 'react';
import { Face } from './Face.tsx';
import { describeCard } from './card-state.ts';
import './card.css';

interface CardProps {
  index: number;
  size: number;
  face: number | null;
  matched: boolean;
  tabIndex: number;
  activate(index: number): void;
  focus(index: number, card: HTMLElement): void;
  clicked(card: HTMLElement): void;
}

// Memoized, so a clock tick that changes no card renders none of them.
export const Card = memo(function Card({
  index,
  size,
  face,
  matched,
  tabIndex,
  activate,
  focus,
  clicked,
}: CardProps) {
  const { state, label } = describeCard(index, size, face, matched);
  // Chromium sends no click after a context menu, a long press or a touch scroll, so every click
  // activates.
  return (
    <button
      type="button"
      className={`card ${state}`}
      aria-label={label}
      aria-disabled={matched}
      tabIndex={tabIndex}
      onFocus={(event) => focus(index, event.currentTarget)}
      onClick={(event) => {
        activate(index);
        clicked(event.currentTarget);
      }}
    >
      {face === null ? <span className="card-back" aria-hidden="true" /> : <Face face={face} />}
      {matched && (
        <svg className="matched-mark" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
          <path d="m2 6 3 3 5-6" fill="none" stroke="currentColor" strokeWidth="2" />
        </svg>
      )}
    </button>
  );
});
import { useCallback, useEffect, useRef } from 'react';
import type { RefObject } from 'react';

interface ScrollPosition {
  readonly left: number;
  readonly top: number;
}

// Chromium centers a card that Tab or Shift+Tab focuses inside the board before focus handlers
// run. Scroll events arrive a frame later, so the last board position they reported still shows
// the view from before that scroll. Restoring it first lets the card scroll from where the player
// was looking, with nearest alignment in the board. The page scroll is left to the browser.
export function useNearestScroll(viewport: RefObject<HTMLElement | null>) {
  const board = useRef<ScrollPosition>({ left: 0, top: 0 });
  useEffect(() => {
    const element = viewport.current;
    function boardScrolled(): void {
      if (element) board.current = { left: element.scrollLeft, top: element.scrollTop };
    }
    boardScrolled();
    element?.addEventListener('scroll', boardScrolled, { passive: true });
    return () => element?.removeEventListener('scroll', boardScrolled);
  }, [viewport]);

  return useCallback(
    (card: HTMLElement): void => {
      viewport.current?.scrollTo(board.current.left, board.current.top);
      card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    },
    [viewport],
  );
}
.board-viewport {
  --card-min: 44px;
  --card-max: 88px;
  --card-gap: 6px;
  --board-padding: 6px;
  --board-border: 1px;
  max-height: min(70dvh, 768px);
  overflow: auto;
  overscroll-behavior: contain;
  padding: var(--board-padding);
  border: var(--board-border) solid var(--border);
  border-radius: 12px;
  background: var(--panel);
  width: fit-content;
  max-width: 100%;
}
.board {
  display: grid;
  gap: var(--card-gap);
  grid-template-columns: repeat(var(--grid-size), minmax(var(--card-min), var(--card-max)));
  /* The scroll area's content box already leaves room for page and board scrollbars. */
  width: clamp(
    calc(var(--grid-size) * var(--card-min) + (var(--grid-size) - 1) * var(--card-gap)),
    100%,
    calc(var(--grid-size) * var(--card-max) + (var(--grid-size) - 1) * var(--card-gap))
  );
}
.card {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  scroll-margin: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
  background: var(--face);
}
.card.matched {
  border-color: var(--green);
}
.card > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.card-back {
  width: 12px;
  height: 12px;
  border: 2px solid var(--secondary);
  transform: rotate(45deg);
}
/* A corner mark wider than about 17% of the card would reach the top-right marker. */
.card > .matched-mark {
  position: absolute;
  right: 0;
  top: 0;
  width: 16%;
  height: 16%;
  color: var(--green);
}
@media (prefers-reduced-motion: reduce) {
  .card {
    transition: none;
  }
}

# Neon Pairs

Neon Pairs is a memory game that runs offline from one HTML file and keeps local best moves for each board size.

You can repeat a deal with its board code, save progress as a snapshot or run timed actions through the replay command.

Status: implements product spec version 2.2.

## Install

Use the named test combination, Node 26.12.1, npm 11.20.0 and Playwright 1.64.1 with Chromium 156.0.8078.4. From this folder, install the locked tools:

```powershell
npm ci --cache .npm-cache
$env:PLAYWRIGHT_BROWSERS_PATH = Join-Path $PWD '.playwright-browsers'
$env:TEMP = Join-Path $PWD '.browser-work'
$env:TMP = $env:TEMP
New-Item -ItemType Directory -Force -Path $env:TEMP | Out-Null
npm exec --cache .npm-cache -- playwright install chromium
```

These settings keep the browser download and temporary files inside the project. Browser tests use fresh contexts. They stop their browser and local HTTP server when they finish.

## Play

Run `npm run build`, then open `dist/index.html` from disk. The game makes no network requests. To keep saved sizes and scores on a stable HTTP origin, run `npm run dev`. Stop it when you finish.

Use Grid size to choose a board. Reveal two cards with a click, tap, Enter or Space. Arrow keys move board focus. Other keys stay with the browser. Tab leaves the board. New Game gives another deal. Restart repeats the current deal.

Open Reproduce a game to load a board code or export progress. Loading an unfinished snapshot pauses it. Resume returns focus to the remembered card and continues the remaining mismatch interval. A completed snapshot loads as completed without Resume. Elapsed time stops at 359999999ms while play continues. The minutes and seconds display reaches 5999:59. Moves stop at 999999. Matching and victory continue at that count. Saved bests use the same move limit.

## Replay

Run `npm run --silent replay -- PATH` with a version 1 replay JSON file. Valid input prints only its final version 1 snapshot JSON to stdout and exits 0. Invalid input prints nothing to stdout, writes a message to stderr and exits nonzero. The command's silent flag suppresses its npm banner so stdout stays JSON. Other npm commands keep their errors and warnings. Replay timestamps can reach the safe integer limit. Elapsed time uses the same cap as browser play.

## Check

Run the checks from this folder:

```powershell
npm run typecheck
npm test
$env:NEON_PAIRS_NAMED_COMBINATION = '1'
npm run test:e2e
npm run format:check
```

`npm test` runs the unit and static checks with Vitest 5.0.5. `test:e2e` type checks and builds current source before opening the new HTML. It also builds the face sheet and session harness as separate diagnostic entries. The game distribution contains no diagnostic entry.

The browser command writes the Node, npm, Playwright and Chromium versions it ran on to `test-results/browser-runtime.json`. With `NEON_PAIRS_NAMED_COMBINATION` set to `1`, it also fails unless they match the named combination. Use the flag for named-combination evidence. Other supported runtimes, such as Node 24.19, run without it.

The locked install, type check, Vitest unit tests, build from current source and Chromium journeys have passed on the named combination with the flag set. Other versions have no test record here.

## Accessibility

Keyboard, card names, atomic turn feedback, reduced motion, touch scrolling and the equivalent zoom layout at 640x400 CSS pixels with device scale 2 have browser checks. The diagnostic face sheet draws all 128 faces at 44px.

Playwright checks Chromium's accessibility tree through a complete keyboard journey. It checks controls, card names, states, turn results, the final summary, Tab exit and New Game. The developer provides this tree evidence and the tool record. You confirm spoken output during acceptance with your screen reader.

Tree record: Chromium 156.0.8078.4 and Playwright 1.64.1. Screen reader: not run. Spoken journey: user acceptance.

Delivered projects from document setups keep the product specification in `docs/`.

Follow the requirements in docs/ for this project.
# Controls
Controls is a specification that defines the game options and reproduction tools in Neon Pairs.

Status: spec version 2.2.

You can start another deal, repeat the current one or load saved progress. Each control keeps the same label, so you can find the same action after a game changes.

## Deal controls

The main controls are:

- C01 - Label the native size select "Grid size". Give it options `4x4`, `6x6`, `8x8`, `10x10`, `12x12`, `14x14` and `16x16`, with numeric side length `N` as each value. After a successful board-code or snapshot load, select the loaded board's size.
- C02 - Label the fresh-deal button "New Game". It creates a fresh seed and keeps the current size.
- C03 - Label the repeat-deal button "Restart". It starts the same board code again.

Changing size, starting and restarting follow the session rules in [Rules](rules.md).

## Reproduction tools

- C04 - Put reproduction controls inside a native `details` element that starts collapsed. Give its summary the exact text "Reproduce a game".

The controls use the board-code and snapshot formats defined in [Reproducibility](reproducibility.md). A board code starts a deal. A snapshot loads progress on a deal.

## Load a board

- C05 - Label the text input "Board code" and limit it to 32 characters. Show the current board code after a new deal, Restart or a successful load. Keep an edited draft when a card action changes the game.

- C06 - Label its button "Load board". Validate the entered code before replacing the current game with that deal's starting state.

For example, loading `np1-4-1` starts its hidden four-column board. Entering that code alone keeps the current game until you select Load board.

## Snapshot tools

- C07 - Label the textarea "Snapshot JSON" and limit it to 65536 characters. The parser also applies the UTF-8 byte limit in the snapshot format.

- C08 - Label the export button "Export snapshot". Fill the textarea with readable version 1 snapshot JSON that you can select and copy manually. Export leaves the game state and clock unchanged. It requires no Clipboard API.

Export `elapsedMs` and a pending mismatch's `remainingMs` as whole milliseconds. A pending mismatch always exports at least 1ms.

- C09 - Label the import button "Load snapshot". Validate the complete draft before replacing the current game. Load unfinished progress paused and show "Loaded snapshot. Select Resume to continue." Load completed progress as completed without pausing and show "Loaded completed snapshot."

- C10 - Show a "Resume" button only while an imported unfinished game is paused. Selecting it clears that pause. Unfinished play continues from the loaded state. While paused, block every card activation and allow board focus movement. On Resume, move focus to the board's remembered tab stop before removing the Resume button. A loaded completed game stays completed and shows no Resume button.

- C11 - On invalid input, keep the current game and the entered draft for correction. Show the exact status for that control:

| Control | Status |
| --- | --- |
| Load board | Invalid board code. |
| Load snapshot | Invalid snapshot. |

- C12 - A loaded completed snapshot keeps the win banner static and plays no celebration. Import doesn't write a best score. Resuming an unfinished snapshot and later winning records a local best under R10.

For example, loading a completed game with fewer moves than the saved best shows that game without replacing the saved record.

## Focus

- C13 - Keep focus on the button used for starting, restarting, loading or exporting. These actions don't move focus to the board. Resume follows C10 because its button disappears. The board's remembered tab stop follows the focus rules in [Input](input.md#focus).

## Replay

- C14 - Keep replay in the developer CLI and game core. V1 has no replay controls in the game UI.

Run `npm run --silent replay -- PATH` to read a replay file. On valid input, print only the final snapshot JSON to stdout and exit 0. On invalid input, print nothing to stdout, write a message to stderr and exit nonzero.

The complete game pack starts in [Neon Pairs](README.md).
